"use strict";const DeepSearch=(()=>{const r="https://codehub-98s6.onrender.com";async function o(t){try{const n=await fetch(`${r}/api/search/google?q=${encodeURIComponent(t)}`,{signal:AbortSignal.timeout(8e3)});if(!n.ok)return null;const e=await n.json();return!e.items||e.items.length===0?null:{source:"Google",items:e.items.slice(0,5).map(s=>({title:s.title,snippet:s.snippet,url:s.link}))}}catch{return null}}async function c(t){try{const n=await fetch(`${r}/api/search/tavily?q=${encodeURIComponent(t)}`,{signal:AbortSignal.timeout(8e3)});if(!n.ok)return null;const e=await n.json();return!e.results||e.results.length===0?null:{source:"Tavily",answer:e.answer||null,items:e.results.slice(0,5).map(s=>({title:s.title,snippet:s.content||s.snippet||"",url:s.url}))}}catch{return null}}async function i(t){const n=await o(t),e=await c(t),s={sources:[],answer:null,items:[]};if(e&&e.answer&&(s.answer=e.answer),n&&n.items.length>0&&(s.sources.push("Google"),s.items.push(...n.items)),e&&e.items.length>0){s.sources.push("Tavily");for(const a of e.items)s.items.find(h=>h.url===a.url)||s.items.push(a)}return s}function l(t){if(!t.items||t.items.length===0)return null;let n="";return t.answer&&(n+=`<div class="deep-search-answer"><strong>Resumen:</strong> ${t.answer}</div>`),n+='<div class="deep-search-sources">',n+=`<span class="deep-search-label">Fuentes (${t.sources.join(" + ")}):</span>`,t.items.forEach((e,s)=>{const a=e.url?new URL(e.url).hostname.replace("www.",""):"";n+=`<a href="${e.url}" target="_blank" rel="noopener" class="deep-search-source">[${s+1}] ${a}</a>`}),n+="</div>",n}function u(t){const n=t.toLowerCase();return["cu\xE1l es","cuales son","qu\xE9 es","que es","qui\xE9n es","quien es","cu\xE1nto vale","cuanto vale","precio","noticias","\xFAltimas noticias","\xFAltimo","actualidad","hoy en d\xEDa","en este momento","2024","2025","2026","busca","buscar","investiga","encuentra","sobre","acerca de","opini\xF3n","opinion","rese\xF1a","comparar","vs","diferencia entre","c\xF3mo se hace","como se hace","tutorial","paso a paso","d\xF3nde","donde","cu\xE1ndo","cuando","cu\xE1nto","cuanto","cu\xE1les","cuales","cu\xE1l","cual"].some(s=>n.includes(s))}return{search:i,formatResults:l,needsSearch:u}})();
